<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref, watch } from "vue";
import {
  Chart,
  Legend,
  LinearScale,
  LineController,
  LineElement,
  PointElement,
  Tooltip,
  type ChartDataset,
} from "chart.js";
import annotationPlugin from "chartjs-plugin-annotation";
import { cssVar } from "@/Utils/Helpers";

Chart.register(
  LineController,
  LineElement,
  PointElement,
  LinearScale,
  Legend,
  Tooltip,
  annotationPlugin,
);

// Values over time on one y axis, each series a line through its points.
export interface Series {
  label: string;
  color: string;
  points: { x: number; y: number }[];
  dashed?: boolean;
}

const props = defineProps<{
  series: Series[];
  range: [number, number];
  resets: number[];
  now: number;
  // y from 0 to 100%
  percent?: boolean;
}>();

const canvas = ref<HTMLCanvasElement | null>(null);
let chart: Chart | null = null;

const date = (x: number) =>
  new Date(x).toLocaleDateString(undefined, { month: "short", day: "numeric" });
const amount = (y: number) =>
  props.percent
    ? `${y.toLocaleString("en-US", { maximumFractionDigits: 1 })}%`
    : y.toLocaleString("en-US", { maximumFractionDigits: 0 });

function config() {
  const muted = cssVar("--text-muted", "#b7b7b7");
  const border = cssVar("--border-very-muted", "#6969693b");
  const datasets: ChartDataset<"line">[] = [];
  const scales: Record<string, any> = {
    x: {
      type: "linear",
      min: props.range[0],
      max: props.range[1],
      afterBuildTicks: (scale) => {
        scale.ticks = props.resets.map((value) => ({ value }));
      },
      ticks: { color: muted, callback: (x: number) => date(x) },
      grid: { color: border },
    },
    y: {
      type: "linear",
      ...(props.percent && { min: 0, max: 100 }),
      // a fixed width, so graphs stacked on the same range line up
      afterFit: (scale) => (scale.width = 80),
      ticks: { color: muted, callback: amount },
      grid: { color: border },
    },
  };
  for (const series of props.series) {
    const color = cssVar(series.color, "#f0f0f0");
    datasets.push({
      label: series.label,
      data: series.points,
      borderColor: color,
      borderWidth: 1.5,
      borderDash: series.dashed ? [6, 4] : [],
      backgroundColor: color,
      pointRadius: 3,
      pointHoverRadius: 5,
    });
  }
  const line = (x: number, color: string, label?: string) => ({
    type: "line",
    xMin: x,
    xMax: x,
    borderColor: color,
    borderWidth: 1,
    label: label
      ? {
          display: true,
          content: label,
          position: "start",
          color: muted,
          backgroundColor: "transparent",
        }
      : undefined,
  });
  return {
    type: "line" as const,
    data: { datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false as const,
      parsing: false as const,
      scales,
      interaction: { mode: "nearest" as const, intersect: true },
      plugins: {
        legend: {
          labels: { color: muted, boxHeight: 2 },
        },
        tooltip: {
          callbacks: {
            title: (items) => new Date(items[0].parsed.x).toLocaleString(),
            label: (item) => `${item.dataset.label}: ${amount(item.parsed.y)}`,
          },
        },
        annotation: {
          annotations: {
            now: line(props.now, muted, "Now"),
          },
        },
      },
    },
  };
}

onMounted(() => {
  chart = new Chart(canvas.value, config() as any);
});
watch(
  () => [props.series, props.range, props.resets, props.now, props.percent],
  () => {
    const next = config();
    chart.data = next.data;
    chart.options = next.options as any;
    chart.update();
  },
  { deep: true },
);
onBeforeUnmount(() => chart?.destroy());
</script>

<template>
  <div class="relative h-80 w-full">
    <canvas ref="canvas" aria-label="Income graph"></canvas>
  </div>
</template>
